<?php
// Auto Deploy Logo Script
$dir = __DIR__ . '/images/';
if (!is_dir($dir)) {
    mkdir($dir, 0755, true);
}

$pngData = base64_decode('');
file_put_contents($dir . 'aplikasi-premium-logo.png', $pngData);

$jpgData = base64_decode('');
file_put_contents($dir . 'aplikasi-premium-logo.jpg', $jpgData);

echo '<h2>Logo Aplikasi Premium Berhasil Dibuat!</h2>';
echo '<p>PNG Size: ' . strlen($pngData) . ' bytes</p>';
echo '<p>JPG Size: ' . strlen($jpgData) . ' bytes</p>';
echo '<p><img src="/images/aplikasi-premium-logo.png" width="200" style="background: #1e293b; padding: 10px; border-radius: 12px;"></p>';
echo '<p><a href="/">Kembali ke Beranda</a></p>';
